-- Cloudflare D1 uses SQLite. IDs and timestamps are generated by the Worker so
-- imports can retain their Supabase IDs and relationships during cutover.
PRAGMA foreign_keys = ON;

CREATE TABLE app_users (
  id TEXT PRIMARY KEY,
  clerk_user_id TEXT UNIQUE,
  legacy_supabase_user_id TEXT UNIQUE,
  email TEXT NOT NULL UNIQUE COLLATE NOCASE,
  full_name TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE TABLE user_roles (
  user_id TEXT NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,
  role TEXT NOT NULL CHECK (role IN ('super_admin', 'registration_staff', 'collector', 'household_member', 'hoa_viewer')),
  granted_by TEXT REFERENCES app_users(id) ON DELETE SET NULL,
  granted_at TEXT NOT NULL,
  PRIMARY KEY (user_id, role)
);

CREATE TABLE addresses (
  id TEXT PRIMARY KEY,
  property_reference TEXT,
  address_line_1 TEXT NOT NULL,
  address_line_2 TEXT,
  suburb TEXT NOT NULL,
  city TEXT NOT NULL DEFAULT 'Gaborone',
  district TEXT,
  postal_code TEXT,
  country_code TEXT NOT NULL DEFAULT 'BW' CHECK (length(country_code) = 2),
  latitude REAL,
  longitude REAL,
  access_notes TEXT,
  verification_status TEXT NOT NULL DEFAULT 'pending' CHECK (verification_status IN ('pending', 'verified', 'rejected')),
  verification_method TEXT,
  verification_notes TEXT,
  verified_by TEXT REFERENCES app_users(id) ON DELETE SET NULL,
  verified_at TEXT,
  created_by TEXT REFERENCES app_users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE UNIQUE INDEX addresses_property_reference_unique ON addresses(lower(property_reference)) WHERE property_reference IS NOT NULL;
CREATE INDEX addresses_location_search ON addresses(suburb, city, address_line_1);

CREATE TABLE households (
  id TEXT PRIMARY KEY,
  household_code TEXT NOT NULL UNIQUE COLLATE NOCASE,
  name TEXT NOT NULL,
  address_id TEXT NOT NULL REFERENCES addresses(id) ON DELETE RESTRICT,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'verified', 'active', 'suspended', 'withdrawn')),
  registration_source TEXT NOT NULL DEFAULT 'admin_event',
  operational_notes TEXT,
  consent_version TEXT,
  consented_at TEXT,
  registered_by TEXT REFERENCES app_users(id) ON DELETE SET NULL,
  registered_at TEXT NOT NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX households_address_id_idx ON households(address_id);
CREATE INDEX households_status_idx ON households(status);

CREATE TABLE household_memberships (
  id TEXT PRIMARY KEY,
  household_id TEXT NOT NULL REFERENCES households(id) ON DELETE RESTRICT,
  user_id TEXT REFERENCES app_users(id) ON DELETE SET NULL,
  full_name TEXT NOT NULL,
  email TEXT NOT NULL COLLATE NOCASE,
  phone TEXT,
  member_type TEXT NOT NULL DEFAULT 'member' CHECK (member_type IN ('primary_contact', 'member')),
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'invited', 'active', 'revoked')),
  invited_at TEXT,
  activated_at TEXT,
  revoked_at TEXT,
  created_by TEXT REFERENCES app_users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE UNIQUE INDEX household_memberships_user_unique ON household_memberships(household_id, user_id) WHERE user_id IS NOT NULL;
CREATE UNIQUE INDEX household_memberships_open_email_unique ON household_memberships(household_id, email) WHERE status <> 'revoked';
CREATE UNIQUE INDEX household_memberships_primary_contact_unique ON household_memberships(household_id) WHERE member_type = 'primary_contact' AND status <> 'revoked';

CREATE TABLE collector_household_assignments (
  id TEXT PRIMARY KEY,
  collector_user_id TEXT NOT NULL REFERENCES app_users(id) ON DELETE RESTRICT,
  household_id TEXT NOT NULL REFERENCES households(id) ON DELETE RESTRICT,
  assigned_by TEXT REFERENCES app_users(id) ON DELETE SET NULL,
  assigned_at TEXT NOT NULL,
  ended_at TEXT
);
CREATE UNIQUE INDEX collector_household_assignments_active_unique ON collector_household_assignments(collector_user_id, household_id) WHERE ended_at IS NULL;

CREATE TABLE businesses (
  id TEXT PRIMARY KEY,
  request_key TEXT NOT NULL,
  registered_name TEXT NOT NULL DEFAULT '',
  trading_name TEXT NOT NULL DEFAULT '',
  registration_number TEXT,
  registration_exception TEXT NOT NULL DEFAULT '',
  country_code TEXT NOT NULL DEFAULT 'BW' CHECK (length(country_code) = 2),
  industry TEXT NOT NULL DEFAULT '',
  contact_name TEXT NOT NULL DEFAULT '',
  contact_role TEXT NOT NULL DEFAULT '',
  contact_email TEXT NOT NULL DEFAULT '',
  contact_phone TEXT NOT NULL DEFAULT '',
  service_needs TEXT NOT NULL DEFAULT '',
  verification_status TEXT NOT NULL DEFAULT 'draft' CHECK (verification_status IN ('draft', 'submitted', 'under_review', 'changes_requested', 'verified', 'rejected')),
  service_status TEXT NOT NULL DEFAULT 'inactive' CHECK (service_status IN ('inactive', 'active', 'suspended')),
  version INTEGER NOT NULL DEFAULT 1,
  created_by TEXT NOT NULL REFERENCES app_users(id) ON DELETE RESTRICT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE (created_by, request_key)
);
CREATE UNIQUE INDEX business_registration_unique ON businesses(country_code, lower(registration_number)) WHERE registration_number IS NOT NULL;
CREATE UNIQUE INDEX business_name_unique ON businesses(country_code, lower(trim(registered_name))) WHERE trim(registered_name) <> '';

CREATE TABLE business_sites (
  id TEXT PRIMARY KEY,
  business_id TEXT NOT NULL REFERENCES businesses(id) ON DELETE RESTRICT,
  name TEXT NOT NULL,
  address TEXT NOT NULL,
  city TEXT NOT NULL,
  contact_name TEXT NOT NULL DEFAULT '',
  contact_email TEXT NOT NULL DEFAULT '',
  contact_phone TEXT NOT NULL DEFAULT '',
  operating_hours TEXT NOT NULL DEFAULT '',
  access_notes TEXT NOT NULL DEFAULT '',
  container_notes TEXT NOT NULL DEFAULT '',
  timezone TEXT NOT NULL DEFAULT 'Africa/Gaborone',
  verification_status TEXT NOT NULL DEFAULT 'pending' CHECK (verification_status IN ('pending', 'verified', 'rejected')),
  service_status TEXT NOT NULL DEFAULT 'inactive' CHECK (service_status IN ('inactive', 'active')),
  UNIQUE (business_id, id)
);
CREATE UNIQUE INDEX business_site_address_unique ON business_sites(business_id, lower(trim(address)), lower(trim(city))) WHERE trim(address) <> '';
CREATE UNIQUE INDEX business_site_name_unique ON business_sites(business_id, lower(trim(name))) WHERE trim(name) <> '';

CREATE TABLE business_evidence (
  id TEXT PRIMARY KEY,
  business_id TEXT NOT NULL UNIQUE REFERENCES businesses(id) ON DELETE RESTRICT,
  reference TEXT NOT NULL DEFAULT '',
  notes TEXT NOT NULL DEFAULT ''
);

CREATE TABLE business_reviews (
  id TEXT PRIMARY KEY,
  business_id TEXT NOT NULL REFERENCES businesses(id) ON DELETE RESTRICT,
  site_id TEXT,
  action TEXT NOT NULL,
  reason TEXT NOT NULL,
  evidence_reference TEXT NOT NULL DEFAULT '',
  reviewed_by TEXT NOT NULL REFERENCES app_users(id) ON DELETE RESTRICT,
  created_at TEXT NOT NULL,
  FOREIGN KEY (business_id, site_id) REFERENCES business_sites(business_id, id)
);

CREATE TABLE business_memberships (
  id TEXT PRIMARY KEY,
  business_id TEXT NOT NULL REFERENCES businesses(id) ON DELETE RESTRICT,
  user_id TEXT REFERENCES app_users(id) ON DELETE SET NULL,
  email TEXT NOT NULL COLLATE NOCASE,
  full_name TEXT NOT NULL,
  role TEXT NOT NULL DEFAULT 'business_admin' CHECK (role IN ('business_admin', 'site_contact')),
  site_id TEXT,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'invited', 'active', 'revoked')),
  invited_at TEXT,
  activated_at TEXT,
  FOREIGN KEY (business_id, site_id) REFERENCES business_sites(business_id, id),
  CHECK ((role = 'business_admin' AND site_id IS NULL) OR (role = 'site_contact' AND site_id IS NOT NULL))
);
CREATE UNIQUE INDEX business_membership_email_unique ON business_memberships(business_id, email) WHERE status <> 'revoked';
CREATE INDEX business_memberships_user_idx ON business_memberships(user_id);

CREATE TABLE business_invitation_attempts (
  id TEXT PRIMARY KEY,
  membership_id TEXT NOT NULL REFERENCES business_memberships(id) ON DELETE RESTRICT,
  requested_by TEXT NOT NULL REFERENCES app_users(id) ON DELETE RESTRICT,
  status TEXT NOT NULL DEFAULT 'started' CHECK (status IN ('started', 'sent', 'failed', 'linked')),
  error_code TEXT,
  created_at TEXT NOT NULL
);
CREATE INDEX business_invitation_time_idx ON business_invitation_attempts(membership_id, created_at);

CREATE TABLE audit_logs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  table_name TEXT NOT NULL,
  record_id TEXT,
  action TEXT NOT NULL CHECK (action IN ('insert', 'update', 'delete')),
  actor_user_id TEXT REFERENCES app_users(id) ON DELETE SET NULL,
  old_values TEXT,
  new_values TEXT,
  occurred_at TEXT NOT NULL
);
CREATE INDEX audit_logs_record_idx ON audit_logs(table_name, record_id, occurred_at DESC);
CREATE INDEX audit_logs_actor_idx ON audit_logs(actor_user_id, occurred_at DESC);
